function statusText(l){return l.status==='ready'?'ГОТОВА':l.status==='error'?'ОШИБКА':l.status==='cancelled'?'ОТМЕНЕНА':l.status==='processing'?'ОБРАБОТКА':'ГОТОВИТСЯ'}
function qualityLabel(l){return /^https:\/\//i.test(l.source||'')?(l.quality==='best'?'лучшее доступное':`до ${l.quality}p`):''}
function shortTime(s){s=Math.max(0,Math.round(s));return s<60?`${s} сек.`:`${Math.floor(s/60)} мин. ${s%60} сек.`}
function observeEta(l,fresh=false){if(l._etaObservedAt&&!fresh)return l;const startTs=Number(l.started_at)||(l.created_at?Date.parse(String(l.created_at).replace(' ','T')+'Z')/1000:0),elapsed=startTs>0?Math.max(0,Math.floor(Date.now()/1000-startTs)):0,pct=Number(l.progress)||0;l._etaObservedAt=Date.now();l._etaAtUpdate=typeof l.eta_seconds==='number'&&l.eta_seconds>=0?l.eta_seconds:l.status==='processing'&&pct>=10&&elapsed>4?Math.max(3,Math.round(elapsed*(100-pct)/pct)):null;return l}
function etaText(l){
  if(l.status!=='processing'&&l.status!=='queued')return '';
  if(l.status==='queued')return 'В очереди на обработку…';
  const startTs=Number(l.started_at)||(l.created_at?Date.parse(String(l.created_at).replace(' ','T')+'Z')/1000:0);
  const elapsed=startTs>0?Math.max(0,Math.floor(Date.now()/1000-startTs)):0;
  const elapsedText=`Прошло ${shortTime(elapsed)}`;
  const observedAt=Number(l._etaObservedAt)||Date.now();
  const observedEta=typeof l._etaAtUpdate==='number'?l._etaAtUpdate:(typeof l.eta_seconds==='number'?l.eta_seconds:null);
  if(observedEta!==null&&observedEta>=0){
    const remaining=Math.max(0,observedEta-Math.floor((Date.now()-observedAt)/1000));
    return remaining?`${elapsedText} · примерно осталось ${shortTime(remaining)}`:`${elapsedText} · завершаем текущий этап`;
  }
  if(l.speed&&l.status==='processing'){
    const pct=Number(l.progress)||0;
    if(pct>=10&&elapsed>4){
      const estRem=Math.max(3,Math.round(elapsed*(100-pct)/pct));
      return `${elapsedText} · осталось ~${shortTime(estRem)} · ${l.speed}`;
    }
    return `${elapsedText} · ${l.speed}`;
  }
  const pct=Number(l.progress)||0;
  if(pct>=12&&elapsed>4){
    const estRemaining=Math.max(4,Math.round(elapsed*(100-pct)/pct));
    return `${elapsedText} · осталось примерно ${shortTime(estRemaining)}`;
  }
  return elapsed>0?`${elapsedText} · подготовка`:'Подготовка к обработке…';
}
function progressMarkup(l,large=false){const pct=Math.max(0,Math.min(100,Number(l.progress)||0)),queued=l.status==='queued';return `<div class="job-progress ${large?'job-progress-large':''}"><div class="job-progress-head"><span>${esc(queued?'Подготовка к обработке':l.stage||'Обработка')}</span><b>${pct}%</b></div><div class="progress-track ${queued||pct===0?'indeterminate':''}" role="progressbar" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><i style="width:${pct}%"></i></div><small>${esc(etaText(l))}</small></div>`}
