function uploadFileWithProgress(form){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();uploadRequest=xhr;xhr.open('POST','/api/lectures/upload');xhr.withCredentials=true;const uploadStartTime=Date.now();xhr.upload.onprogress=e=>{if(e.lengthComputable){const pct=Math.round(e.loaded/e.total*100);const elapsedSec=Math.max(0.1,(Date.now()-uploadStartTime)/1000);const speedBytes=e.loaded/elapsedSec;const speedText=formatBytes(speedBytes)+'/с';const remSec=Math.max(0,Math.round((e.total-e.loaded)/speedBytes));$('#uploadProgressFill').style.width=`${pct}%`;$('#uploadProgressLabel').textContent=`Передача видео · ${pct}% · ${speedText} (осталось ~${shortTime(remSec)})`}};xhr.upload.onload=()=>{$('#uploadProgressFill').style.width='100%';$('#uploadProgressLabel').textContent='Видео передано · шифруем и ставим в очередь…'};xhr.onerror=()=>reject(Error('Не удалось связаться с сервером'));xhr.onabort=()=>reject(Error('Загрузка отменена'));xhr.onload=()=>{let body={};try{body=JSON.parse(xhr.responseText)}catch{}if(xhr.status>=200&&xhr.status<300)resolve(body);else reject(Error(body.detail||'Не удалось загрузить файл'))};xhr.send(form)})}
