orb.onclick=()=>{$('#orbPopover').classList.toggle('shown');$('#searchInput').focus({preventScroll:true});document.querySelector('.search-wrap').scrollIntoView({behavior:'smooth',block:'center'})};orb.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();orb.click()}};

function subtitleTime(seconds,separator=','){const ms=Math.round((Number(seconds)||0)*1000),whole=Math.floor(ms/1000),h=Math.floor(whole/3600),m=Math.floor(whole%3600/60),s=whole%60;return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}${separator}${String(ms%1000).padStart(3,'0')}`}
function exportTranscript(format){if(!segments.length)return;const rows=segments.map((segment,index)=>({start:Number(segment.start)||0,end:Number(segment.end)||Number(segments[index+1]?.start)||Number(activeLecture.duration)||((Number(segment.start)||0)+3),text:String(translatedLectureId===activeLecture?.id&&translatedSegments[index]||segment.text||'')}));let content,mime;if(format==='txt'){content=rows.map(row=>`${stamp(row.start)}\t${row.text}`).join('\n');mime='text/plain;charset=utf-8'}else if(format==='srt'){content=rows.map((row,index)=>`${index+1}\n${subtitleTime(row.start)} --> ${subtitleTime(row.end)}\n${row.text}`).join('\n\n');mime='application/x-subrip;charset=utf-8'}else{content='WEBVTT\n\n'+rows.map(row=>`${subtitleTime(row.start,'.')} --> ${subtitleTime(row.end,'.')}\n${row.text}`).join('\n\n');mime='text/vtt;charset=utf-8'}const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=(activeLecture.title||'лекция').replace(/[\\/:*?"<>|]+/g,'_')+'.'+format;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

async function requestSubtitleBatch(id,language,offset,limit){try{return await api(`/api/lectures/${id}/subtitles/translate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target_language:language,offset,limit})})}catch(error){if(limit>3&&/(не удалось надёжно разобрать перевод|не удалось перевести эту часть)/i.test(error.message||'')){const leftSize=Math.floor(limit/2),left=await requestSubtitleBatch(id,language,offset,leftSize),right=await requestSubtitleBatch(id,language,offset+leftSize,limit-leftSize);return{total:left.total,offset,items:[...left.items,...right.items]}}throw error}}
function addTranslatedCaptionTrack(player,source,translated,language){
  const existing=player.querySelector('track[data-translated-caption]');if(existing)existing.remove();
  if(subtitleBlobUrl)URL.revokeObjectURL(subtitleBlobUrl);
  const time=value=>subtitleTime(value,'.');
  const cues=source.map((item,index)=>`${time(item.start)} --> ${time(item.end||source[index+1]?.start||Number(activeLecture?.duration)||Number(item.start)+3)}\n${translated[index]||item.text}`).join('\n\n');
  const blob=new Blob([`WEBVTT\n\n${cues}\n`],{type:'text/vtt'});subtitleBlobUrl=URL.createObjectURL(blob);
  const labels={en:'English',zh:'中文',de:'Deutsch',es:'Español',ru:'Русский'};const track=document.createElement('track');track.kind='subtitles';track.label=`${labels[language]||language} · ${window.t?.('Перевод')||'Перевод'}`;track.srclang=language;track.src=subtitleBlobUrl;track.default=true;track.dataset.translatedCaption='true';player.append(track);
  const activate=()=>{try{track.track.mode='showing';if(activePlyr?.toggleCaptions)activePlyr.toggleCaptions(true)}catch{}};track.addEventListener('load',activate,{once:true});setTimeout(activate,250);
}

async function openLecture(id,seek=0){if(activeLecturePoll){clearInterval(activeLecturePoll);activeLecturePoll=null}const cached=lectures.find(l=>l.id===id);activeLecture=cached?observeEta(cached):observeEta(await api(`/api/lectures/${id}`),true);const modal=$('#detailModal');modal.classList.remove('hidden');await renderDetail(seek);if(activeLecture.status==='processing'||activeLecture.status==='queued'){activeLecturePoll=setInterval(async()=>{if($('#detailModal').classList.contains('hidden')||activeLecture?.id!==id){clearInterval(activeLecturePoll);activeLecturePoll=null;return}try{activeLecture=observeEta(await api(`/api/lectures/${id}`),true);await renderDetail(seek);if(!['processing','queued'].includes(activeLecture.status)){clearInterval(activeLecturePoll);activeLecturePoll=null;loadLectures()}}catch{clearInterval(activeLecturePoll);activeLecturePoll=null}},1500)}}
function processingPanel(l){if(l.status==='error')return `<div class="processing-box error-box"><b>Не удалось обработать речь</b><p>Файл уже загружен и сохранён. Ошибка возникла на этапе обработки: ${esc(l.error||'Попробуйте запустить обработку ещё раз.')}</p>${l.video_url?`<div class="error-video-preview"><video controls preload="metadata" playsinline src="${esc(l.video_url)}" aria-label="Загруженное видео лекции"></video></div>`:''}<button class="primary-button" id="retryLecture">Повторить обработку <span>↻</span></button></div>`;if(l.status==='cancelled')return `<div class="processing-box"><b>Обработка остановлена</b><p>Видео можно обработать позже.</p><button class="primary-button" id="retryLecture">Продолжить обработку <span>↻</span></button></div>`;return `<div class="processing-box"><b><span class="spin">◌</span>${l.status==='queued'?'Лекция принята':'Обрабатываем лекцию'}</b>${progressMarkup(l,true)}<button class="cancel-job-button" id="cancelLecture">Отменить обработку</button><p class="processing-note">Можно закрыть это окно — обработка продолжится.</p></div>`}
async function renderDetail(seek=0){if(activeLecture.status==='processing'||activeLecture.status==='queued'){const box=$('#detailContent .processing-box');if(box){const head=box.querySelector('.job-progress-head');const bar=box.querySelector('[role=progressbar]');const foot=box.querySelector('.job-progress small');const spin=box.querySelector('b');if(head&&bar&&foot){const pct=Math.max(0,Math.min(100,Number(activeLecture.progress)||0));if(spin)spin.innerHTML=`<span class="spin">◌</span>${activeLecture.status==='queued'?'Лекция принята':'Обрабатываем лекцию'}`;head.querySelector('span').textContent=activeLecture.status==='queued'?'Подготовка к обработке':activeLecture.stage||'Обработка';head.querySelector('b').textContent=`${pct}%`;bar.className=`progress-track ${activeLecture.status==='queued'||pct===0?'indeterminate':''}`;bar.setAttribute('aria-valuenow',pct);bar.querySelector('i').style.width=`${pct}%`;foot.textContent=etaText(activeLecture);return;}}}if(activePlyr){activePlyr.destroy();activePlyr=null}const id=activeLecture.id;const folderSel=$('#moveLectureFolder');if(folderSel){folderSel.innerHTML='<option value="">Без папки</option>'+folders.map(f=>`<option value="${esc(f.id)}" ${activeLecture.folder_id===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}const panel=activeLecture.status==='ready'?`<div class="detail-grid"><div><div class="video-frame" id="videoFrame">${activeLecture.video_url?`<video id="player" playsinline src="${esc(activeLecture.video_url)}"></video>`:'<div class="player-placeholder">Видео ещё не доступно</div>'}</div><div class="detail-tabs"><button class="active" data-panel="transcript">Транскрипт</button><button data-panel="chapters">Главы</button><div class="transcript-exports" id="transcriptExports" aria-label="Скачать текст с таймкодами"><button type="button" data-export="txt">TXT</button><button type="button" data-export="srt">SRT</button><button type="button" data-export="vtt">VTT</button></div></div><div id="transcriptList" class="transcript-list">Загружаем транскрипт…</div></div><aside class="detail-side"><h3>Краткий пересказ</h3><div class="summary-text">${esc(activeLecture.summary||'Конспект появится после обработки.')}</div><div class="outline-title-row"><h3 style="margin-top:20px">Оглавление</h3><button class="outline-button rebuild-outline" id="rebuildOutline" type="button" title="Пересчитать пересказ и названия глав">Обновить пересказ и главы</button><button class="outline-button rebuild-outline" id="retryLecture" type="button" title="Заново распознать сохранённое видео">Перераспознать речь</button></div><div id="chapterList">${(activeLecture.outline||[]).map(c=>`<div class="chapter" data-time="${c.time}"><time>${stamp(c.time).slice(3)}</time><span>${esc(c.title)}</span></div>`).join('')||'<p class="summary-text">Разделы появятся после обработки.</p>'}</div><div class="keyword-list">${(activeLecture.keywords||[]).map(k=>`<span class="keyword">${esc(k)}</span>`).join('')}</div></aside></div>`:processingPanel(activeLecture);$('#detailContent').innerHTML=`<div class="detail-head"><div><h2>${esc(activeLecture.title)}</h2><div class="detail-sub">${activeLecture.status==='ready'?`${stamp(activeLecture.duration)} · ${qualityLabel(activeLecture)} · обработано локально`:statusText(activeLecture)}</div></div></div>${panel}`;
const rebuild=$('#rebuildOutline');if(rebuild)rebuild.onclick=async()=>{rebuild.disabled=true;rebuild.textContent='Составляем…';try{const result=await api(`/api/lectures/${id}/outline/rebuild`,{method:'POST'});activeLecture.outline=result.outline;activeLecture.summary=result.summary;activeLecture.keywords=result.keywords;$('#detailContent .summary-text').textContent=result.summary;$('#detailContent .keyword-list').innerHTML=result.keywords.map(k=>`<span class="keyword">${esc(k)}</span>`).join('');$('#chapterList').innerHTML=result.outline.map(c=>`<div class="chapter" data-time="${c.time}"><time>${stamp(c.time).slice(3)}</time><span>${esc(c.title)}</span></div>`).join('')||'<p class="summary-text">Разделы не найдены.</p>';$('#chapterList').onclick=e=>{const row=e.target.closest('.chapter');if(row)seekTo(Number(row.dataset.time))};rebuild.textContent='Готово'}catch(err){rebuild.textContent=err.message}finally{rebuild.disabled=false}};
$('#moveLectureFolder').onchange=async e=>{try{const folder_id=e.target.value||null;await api(`/api/lectures/${id}/folder`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({folder_id})});activeLecture.folder_id=folder_id;upsertLecture(activeLecture);await loadFolders()}catch(err){alert(err.message)}};$('#deleteLecture').onclick=async()=>{if(confirm('Удалить лекцию и её видео?')){await api(`/api/lectures/${id}`,{method:'DELETE'});closeModal($('#detailModal'));loadLectures()}};const retry=$('#retryLecture');if(retry)retry.onclick=async()=>{retry.disabled=true;try{await api(`/api/lectures/${id}/retry`,{method:'POST'});activeLecture=await api(`/api/lectures/${id}`);upsertLecture(activeLecture);await renderDetail(seek);if(activeLecture.status==='processing'||activeLecture.status==='queued')openLecture(id,seek)}catch(e){alert(e.message)}finally{retry.disabled=false}};const cancel=$('#cancelLecture');if(cancel)cancel.onclick=async()=>{cancel.disabled=true;try{await api(`/api/lectures/${id}/cancel`,{method:'POST'});activeLecture=await api(`/api/lectures/${id}`);upsertLecture(activeLecture);await renderDetail(seek)}catch(e){alert(e.message)}finally{cancel.disabled=false}};if(activeLecture.status==='ready'){segments=await api(`/api/lectures/${id}/segments`);if($('#detailModal').classList.contains('hidden')||activeLecture?.id!==id)return;const list=$('#transcriptList');$('#transcriptExports').onclick=event=>{const button=event.target.closest('[data-export]');if(button)exportTranscript(button.dataset.export)};list.innerHTML=segments.map((s,index)=>`<div class="transcript-line" data-time="${s.start}"><time>${stamp(s.start).slice(3)}</time><span>${esc(translatedLectureId===id&&translatedSegments[index]||s.text)}</span></div>`).join('');const translateBar=document.createElement('div');translateBar.className='subtitle-translate-bar';translateBar.innerHTML=`<label><span>Язык перевода</span><select id="subtitleTargetLanguage"><option value="en">🇬🇧 English</option><option value="zh">🇨🇳 中文</option><option value="de">🇩🇪 Deutsch</option><option value="es">🇪🇸 Español</option><option value="ru">🇷🇺 Русский</option></select></label><button type="button" id="translateSubtitles">Перевести субтитры</button><span id="subtitleTranslationStatus" aria-live="polite"></span>`;$('#transcriptExports').parentElement.insertAdjacentElement('afterend',translateBar);if(activeTranslationCode)$('#subtitleTargetLanguage').value=activeTranslationCode;$('#translateSubtitles').onclick=async event=>{const button=event.currentTarget,language=$('#subtitleTargetLanguage').value,status=$('#subtitleTranslationStatus');button.disabled=true;status.textContent='Переводим субтитры…';try{const translated=new Array(segments.length);for(let offset=0;offset<segments.length;offset+=12){const result=await requestSubtitleBatch(id,language,offset,Math.min(12,segments.length-offset));for(const item of result.items)translated[item.index]=item.text;status.textContent=`Переводим субтитры… ${Math.min(100,Math.round((offset+result.items.length)/segments.length*100))}%`}if(translated.some(text=>!text))throw Error('Не удалось перевести субтитры');translatedSegments=translated;translatedLectureId=id;activeTranslationCode=language;list.innerHTML=segments.map((s,index)=>`<div class="transcript-line" data-time="${s.start}"><time>${stamp(s.start).slice(3)}</time><span>${esc(translated[index])}</span></div>`).join('');const player=$('#player');if(player)addTranslatedCaptionTrack(player,segments,translated,language);status.textContent='Субтитры переведены'}catch(error){status.textContent=error.message||'Не удалось перевести субтитры'}finally{button.disabled=false}};list.onclick=e=>{const row=e.target.closest('.transcript-line');if(row)seekTo(Number(row.dataset.time))};$('#chapterList').onclick=e=>{const row=e.target.closest('.chapter');if(row)seekTo(Number(row.dataset.time))};const player=$('#player');if(player){activePlyr=new Plyr(player,{iconUrl:'/static/plyr.svg',title:activeLecture.title,urls:{download:`/api/lectures/${id}/download`},controls:['play-large','play','progress','current-time','mute','volume','captions','download','settings','pip','airplay','fullscreen'],settings:['quality','speed'],ratio:'16:9',hideControls:false,i18n:window.getPlayerTranslations?.(window.getUiLanguage?.())||{play:'Воспроизвести',pause:'Пауза'}});if(translatedLectureId===id&&translatedSegments.length)addTranslatedCaptionTrack(player,segments,translatedSegments,activeTranslationCode);player.ontimeupdate=()=>syncTranscript(player.currentTime);if(seek)seekTo(seek)}$$('.detail-tabs button[data-panel]').forEach(b=>b.onclick=()=>{$$('.detail-tabs button[data-panel]').forEach(x=>x.classList.toggle('active',x===b));if(b.dataset.panel==='chapters'){list.innerHTML=(activeLecture.outline||[]).map(c=>`<div class="transcript-line" data-time="${c.time}"><time>${stamp(c.time).slice(3)}</time><span>${esc(c.title)}</span></div>`).join('')}else{list.innerHTML=segments.map((s,index)=>`<div class="transcript-line" data-time="${s.start}"><time>${stamp(s.start).slice(3)}</time><span>${esc(translatedLectureId===id&&translatedSegments[index]||s.text)}</span></div>`).join('')}})}}
function seekTo(t){const p=$('#player');if(p){p.currentTime=t;p.play().catch(()=>{});syncTranscript(t)}}
function syncTranscript(t){let found=-1;for(let i=0;i<segments.length;i++)if(t>=segments[i].start&&t<=segments[i].end){found=i;break}$$('.transcript-line').forEach((r,i)=>r.classList.toggle('active',i===found));const active=$('.transcript-line.active'),list=$('#transcriptList');if(active&&list){const rowTop=active.offsetTop-list.offsetTop,rowBottom=rowTop+active.offsetHeight;if(rowTop<list.scrollTop)list.scrollTo({top:Math.max(0,rowTop-8),behavior:'smooth'});else if(rowBottom>list.scrollTop+list.clientHeight)list.scrollTo({top:rowBottom-list.clientHeight+8,behavior:'smooth'})}}
async function handleAuthLinks(){const q=new URLSearchParams(location.search),error=q.get('oauth_error'),linked=q.get('linked');if(error){const messages={not_linked:'Сначала привяжите эту соцсеть к аккаунту по паролю.',already_linked:'Эта соцсеть уже связана с другим аккаунтом.',state_expired:'Время входа истекло. Попробуйте ещё раз.',provider_failed:'Не удалось войти через соцсеть. Проверьте настройки OAuth.'};$('#authError').textContent=messages[error]||'Не удалось завершить вход';showAuth();history.replaceState(null,'',location.pathname)}if(linked){$('#accountButton').click();history.replaceState(null,'',location.pathname)}}
init().then(handleAuthLinks);
setInterval(()=>{
  if(activeLecture&&['queued','processing'].includes(activeLecture.status)&&!$('#detailModal').classList.contains('hidden')){
    const foot=$('#detailModal .job-progress small');
    if(foot)foot.textContent=etaText(activeLecture);
  }
  if(lectures.some(l=>['queued','processing'].includes(l.status))){
    for(const l of lectures){
      if(!['queued','processing'].includes(l.status))continue;
      const card=$(`article.lecture-card[data-id="${l.id}"]`);
      if(card){
        const foot=card.querySelector('.job-progress small');
        if(foot)foot.textContent=etaText(l);
      }
    }
  }
},1000);
const heroOrb=$('#searchOrb');
if(heroOrb&&'IntersectionObserver'in window){const heroObserver=new IntersectionObserver(([entry])=>document.body.classList.toggle('hero-scroll-away',entry.intersectionRatio<=.08),{threshold:[0,.08,.12]});heroObserver.observe(heroOrb)}
else{const syncHeroScroll=()=>document.body.classList.toggle('hero-scroll-away',window.scrollY>Math.max(140,window.innerHeight*.45));window.addEventListener('scroll',syncHeroScroll,{passive:true});syncHeroScroll()}
